import {archetypes,operations,regions,newGame,blocked,execute,endTurn,describe} from './game.js';
const $=s=>document.querySelector(s);let storageOK=true;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}}
let legacy=read('ba-legacy',{points:0,wins:0,runs:0,foundation:0});let saved=read('ba-run',null);let s=saved?.version===1&&saved.regions?.length===8?saved:newGame();let category='economia',view='command',audio=false;let context;
const categories={economia:['↗','Econômicas'],politica:['♜','Políticas'],midia:['◉','Midiáticas'],tech:['◇','Tecnológicas'],catastrofe:['☢','Catastróficas']};
function save(){try{localStorage.setItem('ba-run',JSON.stringify(s));localStorage.setItem('ba-legacy',JSON.stringify(legacy));}catch{storageOK=false;}}
function sound(){if(!audio)return;try{context??=new AudioContext();const o=context.createOscillator(),g=context.createGain();o.type='sine';o.frequency.value=320;g.gain.setValueAtTime(.035,context.currentTime);g.gain.exponentialRampToValueAtTime(.001,context.currentTime+.15);o.connect(g).connect(context.destination);o.start();o.stop(context.currentTime+.15);}catch{audio=false;}}
const money=n=>`$${n.toFixed(1)}<small>B</small>`;
function metric(label,value,icon,color='green',suffix='%'){return `<div class="metric ${color}"><div class="metric-label"><span>${icon}</span>${label}</div><strong>${suffix==='B'?money(value):Math.round(value)+'<small>'+suffix+'</small>'}</strong><div class="meter"><i style="width:${suffix==='B'?Math.min(100,value*4):Math.max(0,value)}%"></i></div></div>`;}
// Simplified geographic outlines provide a functional region-selection map.
const land=['80,76 115,56 163,57 198,37 248,53 266,84 242,111 260,142 231,171 222,202 192,180 167,151 137,142 109,112','213,181 250,190 264,214 292,225 330,236 336,267 311,302 298,351 276,384 261,349 248,300 233,275 240,247','319,30 362,21 379,51 354,82 330,70','420,104 457,74 484,70 489,41 503,45 501,90 530,101 553,88 574,113 548,146 514,145 495,165 473,141 445,146','431,169 477,158 513,174 541,212 535,249 512,267 504,311 480,339 457,314 451,275 426,238 413,202','532,97 586,63 652,50 705,64 750,58 803,86 843,105 832,133 787,139 768,171 726,193 724,222 746,241 732,264 709,235 690,216 678,247 659,239 641,204 611,187 590,160 549,161','546,166 573,174 600,204 587,224 561,209','753,295 783,281 815,287 850,319 842,345 811,355 780,340 752,341 737,321','838,374 864,349 870,357 849,388','764,214 774,231 769,248 760,234','771,163 779,149 785,133 790,150 782,176','717,274 751,277 778,285 750,290','548,290 552,318 541,330 540,306'];
function map(){return `<div class="map"><div class="map-top"><span><i class="live-dot"></i> SATÉLITE GLOBAL <b>AO VIVO</b></span><span>GRID 23.55° S / 46.63° W</span></div><svg viewBox="0 0 940 430" role="img" aria-label="Mapa de regiões do mundo"><defs><pattern id="grid" width="47" height="43" patternUnits="userSpaceOnUse"><path d="M 47 0 L 0 0 0 43" fill="none" stroke="#1b2728" stroke-width=".6"/></pattern><pattern id="dots" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#506058"/></pattern></defs><rect width="940" height="430" fill="url(#grid)"/><g fill="#192623" stroke="#44584c" stroke-width="1">${land.map(p=>`<polygon points="${p}"/>`).join('')}</g><g fill="url(#dots)">${land.map(p=>`<polygon points="${p}"/>`).join('')}</g><path d="M290 291 Q340 110 474 116 T724 240" fill="none" stroke="#bca76c" opacity=".3" stroke-dasharray="4 7"/>${s.regions.map((r,i)=>`<g class="map-region ${s.selected===i?'selected':''}" data-region="${i}" role="button" tabindex="0" aria-label="Selecionar ${r.name}"><circle cx="${r.x}" cy="${r.y}" r="20" class="halo"/><circle cx="${r.x}" cy="${r.y}" r="5"/><text x="${r.x}" y="${r.y+37}" text-anchor="middle">${r.name.toUpperCase()}</text></g>`).join('')}</svg><div class="map-bottom"><span><i class="legend green"></i> Sua rede <i class="legend gold"></i> Região selecionada</span><span>8 REGIÕES MONITORADAS</span></div></div>`;}
function regionPanel(){const r=s.regions[s.selected];return `<div class="region-panel"><div><span class="eyebrow">REGIÃO SELECIONADA</span><h3>${r.name} <span>↗</span></h3></div><div class="region-stats">${[['Estabilidade',r.stability],['Corruptibilidade',r.corruption],['PIB',r.gdp],['Imprensa livre',r.press]].map(([n,v])=>`<div><span>${n}</span><b>${Math.round(v)}<small>/100</small></b><div class="meter"><i style="width:${v}%"></i></div></div>`).join('')}</div></div>`;}
function operationCards(){return operations.filter(o=>o.category===category).map(o=>{const reason=blocked(s,o);return `<button class="operation" data-op="${o.id}" ${reason?'disabled':''}><div class="op-top"><span class="op-icon">${categories[o.category][0]}</span><span class="op-cost">${money(o.cost)}</span></div><h3>${o.name}</h3><p>${o.desc}</p><div class="op-effects">${describe(o.effect)}</div><div class="op-bottom">${reason||'Executar operação'}<span>${reason?'⌑':'↗'}</span></div></button>`;}).join('');}
function command(){return `<section class="main-column"><div class="section-heading"><h2>O mundo é seu tabuleiro<span>.</span></h2><span class="tag">VISÃO GEOPOLÍTICA</span></div>${map()}${regionPanel()}<div class="section-heading operations-heading"><h2>Central de operações</h2><span>ESCOLHA SUA PRÓXIMA JOGADA</span></div><div class="tabs" role="tablist">${Object.entries(categories).map(([id,[icon,name]])=>`<button role="tab" aria-selected="${category===id}" class="${category===id?'active':''}" data-category="${id}">${icon} ${name}</button>`).join('')}</div><div class="operations">${operationCards()}</div></section><aside><div class="objective"><span class="eyebrow">OBJETIVO DA PARTIDA</span><div class="objective-icon">◉</div><h2>Leve o mundo<br>ao limite.</h2><p>Alcance 100% de caos global.<br>Mantenha seu nome fora disso.</p><div class="objective-progress"><span>CAOS GLOBAL</span><b>${Math.round(s.chaos)}<small> / 100%</small></b></div><div class="meter"><i style="width:${s.chaos}%"></i></div><div class="warning">△ Exposição em 100% ou patrimônio<br> zerado encerram seu império.</div></div><div class="feed"><div class="feed-title"><h3>Interceptações</h3><span class="live-dot"></span></div><div aria-live="polite">${s.history.slice(0,5).map((h,i)=>`<article class="feed-item ${h.type}"><div class="feed-meta">${i===0?'MAIS RECENTE':'INTEL / '+String(s.turn).padStart(2,'0')}</div><h4>${h.title}</h4><p>${h.text}</p></article>`).join('')}</div></div></aside>`;}
function archive(){return `<section class="full-panel"><span class="eyebrow">DOSSIÊ CONFIDENCIAL</span><h2>Registro de operações</h2><p>As decisões e consequências desta partida.</p>${s.history.map(h=>`<article class="archive-row"><b>${h.title}</b><p>${h.text}</p></article>`).join('')}</section>`;}
function legacyPanel(){return `<section class="full-panel"><span class="eyebrow">O PODER SOBREVIVE A VOCÊ</span><h2>Seu legado</h2><div class="legacy-stats"><div><strong>${legacy.points}</strong><span>PONTOS DISPONÍVEIS</span></div><div><strong>${legacy.wins}</strong><span>VITÓRIAS</span></div><div><strong>${legacy.runs}</strong><span>PARTIDAS ENCERRADAS</span></div></div><div class="legacy-upgrade"><span class="op-icon">♜</span><h3>Fundação privada · nível ${legacy.foundation}</h3><p>Comece cada nova partida com +$1B por nível. Cada vitória concede 3 pontos de legado.</p><button class="primary" id="upgrade" ${legacy.points<3||legacy.foundation>=5?'disabled':''}>${legacy.foundation>=5?'Nível máximo':'Expandir fundação · 3 pontos'}</button></div><p class="muted">Progresso salvo neste navegador. Bônus aplicados à próxima partida.</p></section>`;}
function render(){const a=archetypes.find(a=>a.id===s.archetype);$('#app').innerHTML=`<header><a class="brand" href="#" aria-label="Central de comando"><span class="brand-symbol">B<span>↘</span></span><span>BILLIONAIRE<small>APOCALYPSE</small></span></a><nav>${[['command','◈','Comando'],['archive','▤','Arquivo'],['legacy','♜','Legado']].map(([id,icon,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${icon} ${name}${id==='legacy'?` <small>${legacy.points}</small>`:''}</button>`).join('')}</nav><div class="header-right"><button id="audio" aria-label="${audio?'Desativar':'Ativar'} som">${audio?'♪':'♫'} <span>SOM ${audio?'ON':'OFF'}</span></button><button id="help" aria-label="Como jogar">?</button><span class="secure"><i class="live-dot"></i> CONEXÃO SEGURA</span></div></header><main><div class="run-bar"><div class="run-identity"><span class="avatar">${a.icon}</span><div><span class="eyebrow">IMPÉRIO PRIVADO / ${s.difficulty.toUpperCase()}</span><h1>${a.name}<span>PARTIDA ${String(legacy.runs+1).padStart(3,'0')}</span></h1></div></div><div class="turn-controls"><div class="quarter"><span class="eyebrow">${2027+Math.floor((s.turn-1)/4)} · T${(s.turn-1)%4+1}</span><span>${s.difficulty==='magnata'?'Ações ilimitadas':`${Math.max(0,3-s.actions)} de 3 ações disponíveis`}</span></div><button class="primary" id="end-turn" ${s.status!=='playing'?'disabled':''}>Avançar trimestre <span>→</span></button></div></div><div class="metrics">${metric('Patrimônio',s.money,'$','gold','B')}${metric('Caos global',s.chaos,'◉')}${metric('Influência política',s.politics,'♜')}${metric('Controle de mídia',s.media,'◌')}${metric('Domínio tech',s.tech,'◇')}${metric('Exposição',s.exposure,'◎','red')}</div><div class="content ${view!=='command'?'single':''}">${view==='command'?command():view==='archive'?archive():legacyPanel()}</div><footer><span>B/A <b>O CAPITAL NÃO TEM CONSCIÊNCIA.</b></span><span>${storageOK?'PROGRESSO SALVO LOCALMENTE':'ARMAZENAMENTO INDISPONÍVEL · PROGRESSO TEMPORÁRIO'} <button id="new-run">Nova partida ↗</button></span></footer></main>`;
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render();});document.querySelectorAll('[data-region]').forEach(b=>{const select=()=>{s.selected=+b.dataset.region;save();render();};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>{execute(s,b.dataset.op);finish();});$('#end-turn').onclick=()=>{endTurn(s);finish();};$('#new-run').onclick=()=>setup();$('#audio').onclick=()=>{audio=!audio;sound();render();};$('#help').onclick=help;$('#upgrade')?.addEventListener('click',()=>{if(legacy.points>=3&&legacy.foundation<5){legacy.points-=3;legacy.foundation++;save();render();}});$('.brand').onclick=e=>{e.preventDefault();view='command';render();};}
function finish(){sound();if(s.status!=='playing'&&!s.rewarded){legacy.runs++;if(s.status==='won'){legacy.wins++;legacy.points+=3;}s.rewarded=true;}save();render();if(s.status!=='playing')result();}
function openModal(html){$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function setup(){let chosen=s.archetype;openModal(`<div class="modal-heading"><span class="eyebrow">UM NOVO IMPÉRIO. UMA NOVA QUEDA.</span>${saved||s.actions||s.turn>1?'<button id="close-modal" aria-label="Fechar">✕</button>':''}</div><h2>Quem vai herdar o mundo?</h2><p>Escolha seu arquétipo. Cada partida é uma nova conspiração.</p><div class="archetypes">${archetypes.map(a=>`<button data-arch="${a.id}" class="archetype ${a.id===chosen?'chosen':''}"><span>${a.icon}</span><small>${a.tag}</small><h3>${a.name}</h3><p>${a.desc}</p><b>${a.bonus}</b></button>`).join('')}</div><div class="setup-bottom"><label>Dificuldade <select id="difficulty"><option value="normal">Normal · 3 ações por trimestre</option><option value="magnata">Magnata · ações ilimitadas</option><option value="investigado">Investigado · +30% exposição</option></select></label><button class="primary" id="start">Iniciar império →</button></div><p class="muted">${s.actions||s.turn>1?'Iniciar substitui a partida atual. Seu legado permanece.':'Objetivo: 100% de caos. Evite falência e exposição total.'}</p>`);document.querySelectorAll('[data-arch]').forEach(b=>b.onclick=()=>{chosen=b.dataset.arch;document.querySelectorAll('[data-arch]').forEach(x=>x.classList.toggle('chosen',x===b));});$('#close-modal')?.addEventListener('click',()=>$('#modal').close());$('#start').onclick=()=>{s=newGame(chosen,$('#difficulty').value,legacy);saved=s;category='economia';view='command';save();$('#modal').close();render();};}
function result(){openModal(`<span class="eyebrow">${s.status==='won'?'OBJETIVO CONCLUÍDO':'FIM DA PARTIDA'}</span><div class="result-icon">${s.status==='won'?'♛':'◎'}</div><h2>${s.status==='won'?'O mundo chegou ao limite.':'Todo império tem um fim.'}</h2><p>${s.ending}</p><div class="result-stats"><span>${s.turn} trimestres</span><span>${Math.round(s.chaos)}% de caos</span><span>${s.status==='won'?'+3':'0'} legado</span></div><button class="primary" id="retry">Construir um novo império →</button><button class="text-button" id="inspect">Revisar partida</button>`);$('#retry').onclick=setup;$('#inspect').onclick=()=>$('#modal').close();}
function help(){openModal(`<span class="eyebrow">BRIEFING</span><h2>O poder é um jogo de consequências.</h2><ol><li>Selecione uma região no mapa. O PIB altera a receita; a corruptibilidade altera o controle obtido.</li><li>Execute até três operações por trimestre. Invista em influência, mídia e tecnologia para desbloquear ações.</li><li>Avance o trimestre para receber receita e enfrentar de um a três eventos aleatórios. Mídia reduz exposição.</li><li>Chegue a 100% de caos sem zerar o patrimônio ou atingir 100% de exposição. Perdas têm prioridade se ocorrerem junto da vitória.</li><li>Vitórias concedem legado para melhorar sua fundação nas próximas partidas.</li></ol><p>As regiões e operações são uma simulação satírica e abstrata. A estabilidade regional registra o impacto das suas operações.</p><button id="understood" class="primary">Entendido →</button>`);$('#understood').onclick=()=>$('#modal').close();}
render();if(!saved)setup();else if(s.status!=='playing')result();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_game_state',description:'Consultar recursos, região e operações disponíveis da partida atual.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({status:s.status,turn:s.turn,money:s.money,chaos:s.chaos,exposure:s.exposure,region:s.regions[s.selected].name,available:operations.filter(o=>!blocked(s,o)).map(o=>({id:o.id,name:o.name,cost:o.cost}))})})).catch(()=>{});}catch{}}
